package com.dating.chat.api;

import com.dating.chat.domain.MessageType;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

import java.util.UUID;

/**
 * @param clientMessageId generated by the client once per message and reused on retries: the server never
 *                        stores the same message twice and answers a retry with the original message
 * @param text            TEXT: 1..2000 characters after trimming
 * @param stickerPackCode STICKER: an owned sticker pack (catalog category STICKER_PACK)
 * @param sticker         STICKER: one of the pack's attributes.stickers
 * @param replyToMessageId optional: a message of this chat this one answers
 */
public record SendMessageRequest(
        @NotBlank(message = "Укажите clientMessageId")
        @Size(max = 64, message = "clientMessageId не должен превышать 64 символа")
        String clientMessageId,

        @NotNull(message = "Укажите тип сообщения")
        MessageType type,

        @Size(max = 4000, message = "Сообщение не должно превышать 2000 символов")
        String text,

        @Size(max = 50, message = "Некорректный набор стикеров")
        String stickerPackCode,

        @Size(max = 50, message = "Некорректный стикер")
        String sticker,

        UUID replyToMessageId
) {
    public SendMessageRequest(String clientMessageId, MessageType type, String text, String stickerPackCode,
                              String sticker) {
        this(clientMessageId, type, text, stickerPackCode, sticker, null);
    }
}
